function enterFront(render){if(frontRestoring){currentFront=render;frontRestoring=false;return}if(currentFront===render)return;if(currentFront)frontHistory.push(currentFront);currentFront=render}function leaveFront(){frontHistory=[];currentFront=null;frontRestoring=false}
