function sprite(cls=''){let i=me.avatar_index||0;return `<i class="avatar-sprite ${cls}" style="background-position:${p(i)}"></i>`}function hud(){let s=meters(),d=me.last_impact||{},x=[['freedom','🕊️ 自由度'],['learning','📚 學習效率'],['order','⚖️ 班級秩序'],['empathy','❤️ 同學滿意度'],['community','🤝 班級凝聚力']];return `<aside class="rpg-hud"><div class="hud-player">${sprite('hud-avatar')}<span><b>${me.avatar_id}</b><br>🎒 班級新成員</span></div><b>🏫 CLASS STATUS</b>${x.map(([k,n])=>`<div class="meter"><span>${n}</span><strong>${s[k]}</strong><i style="width:${s[k]}%"></i>${d[k]?`<em>${d[k]>0?'▲':'▼'}${Math.abs(d[k])}</em>`:''}</div>`).join('')}</aside>`}function impactSummary(){let labels={freedom:'🕊️ 自由度',learning:'📚 學習效率',order:'⚖️ 班級秩序',empathy:'❤️ 同學滿意度',community:'🤝 班級凝聚力'},rows=Object.entries(me.last_impact||{});if(!rows.length)return '<div class="impact-result neutral"><b>這個選擇的影響</b><span>本題不會立刻改變班級能力值。</span></div>';let text=rows.map(([key,value])=>'<span>'+labels[key]+' <strong class="'+(value>0?'up':'down')+'">'+(value>0?'+':'')+value+'</strong></span>').join('');return '<div class="impact-result"><b>這個選擇造成的影響</b>'+text+'</div>'}
function login(){enterFront(login);title.textContent='STEP 1｜建立學生身分';app.innerHTML=`<section class="paper login"><p class="eyebrow">STEP 1</p><h1>🎒 建立你的學生身分</h1><p>進入無規則教室前，先確認你的班級與座號。</p><label>班級<select id="class-select"><option value="">請選擇班級 ▼</option>${APP_CONFIG.CLASSES.map(c=>`<option value="${c}">${c}</option>`).join('')}</select></label><label>座號<select id="seat-select"><option value="">請選擇座號 ▼</option>${Array.from({length:APP_CONFIG.STUDENT_COUNT},(_,i)=>`<option value="${i+1}">${String(i+1).padStart(2,'0')}</option>`).join('')}</select></label><p class="privacy">🔒 你的作答會保密，其他同學不會看到你的個人答案。</p><button class="primary" id="confirm-id">確認身分</button></section>`;let id=me||JSON.parse(localStorage.getItem('nrc-id')||'null');if(id){document.querySelector('#class-select').value=id.class||'';document.querySelector('#seat-select').value=id.seat||''}document.querySelector('#confirm-id').onclick=async()=>{let c=document.querySelector('#class-select').value,seat=+document.querySelector('#seat-select').value;if(!c||!seat)return alert('請選擇班級與座號。');me=await GameAPI.call('getStudent',{class:c,seat});localStorage.setItem('nrc-id',JSON.stringify({class:c,seat}));if(me&&me.avatar_id){me.flow='hub';return hub()}me=await GameAPI.call('student',{class:c,seat,data:{flow:'character',class_state:{freedom:50,learning:50,order:50,empathy:50,community:50}}});character()}}
