function character(){enterFront(character);title.textContent='STEP 2｜選擇角色';app.innerHTML=`<section class="paper character-page"><p class="eyebrow">CHOOSE YOUR CHARACTER</p><h1>選擇你的冒險角色</h1><p>選一位角色，陪你進入無規則教室。</p><div class="avatar-grid">${names.map((n,i)=>`<button class="choice avatar-card ${n===me?.avatar_id?'picked':''}" data-i="${i}"><i style="background-position:${p(i)}"></i><span>${n}</span></button>`).join('')}</div></section>`;document.querySelectorAll('.avatar-card').forEach(b=>b.onclick=()=>confirmCharacter(+b.dataset.i))}
