function choices(s){return `<div class="options">${s.options.map((x,i)=>`<button class="choice" data-v="${esc(x)}"><b>${s.multi?'□':L(i)+'.'}</b>${esc(x)}</button>`).join('')}</div><button class="primary" id="answer" disabled>確認選擇</button>`}function bind(s){let select=[];document.querySelectorAll('.choice').forEach(b=>b.onclick=()=>{let v=b.dataset.v;if(s.multi){select.includes(v)?select=select.filter(x=>x!==v):select.push(v);document.querySelectorAll('.choice').forEach(x=>x.classList.toggle('picked',select.includes(x.dataset.v)))}else{select=[v];document.querySelectorAll('.choice').forEach(x=>x.classList.toggle('picked',x===b))}document.querySelector('#answer').disabled=!select.length});document.querySelector('#answer').onclick=async()=>{let a=s.multi?select:select[0],d={[s.field]:a};if(s.id==='phone_after'){d.phone_changed=me.phone_initial!==a;let shifts=[{freedom:3,order:-2},{order:4,learning:3,empathy:2},{freedom:2,order:-1},{community:2,order:1}],change=shifts[s.options.indexOf(a)]||{},state=meters();Object.entries(change).forEach(([k,v])=>state[k]=Math.max(0,Math.min(100,state[k]+v)));d={...d,class_state:state,last_impact:change}}if(s.unlock)d.unlocked=[...(me.unlocked||[]),s.unlock];await save(d);render()}}
