document.addEventListener('click',async e=>{let b=e.target.closest&&e.target.closest('.l2-choice'),heading=document.querySelector('.l2-panel h1')?.textContent;if(!b||heading!=='重新制定午休規範')return;e.preventDefault();e.stopImmediatePropagation();let id=JSON.parse(localStorage.getItem('nrc-id')||'null'),p=id&&await GameAPI.call('getStudent',id);if(!p||p.level2_phase!=='final')return;let i=+b.dataset.i,changes=[{order:2,freedom:-1},{order:2,learning:2,empathy:2},{freedom:2,order:-1},{community:1}],change=changes[i]||{},state={freedom:50,learning:50,order:50,empathy:50,community:50,...(p.class_state||{})};Object.entries(change).forEach(([k,v])=>state[k]=Math.max(0,Math.min(100,state[k]+v)));document.dispatchEvent(new CustomEvent('level2-action',{detail:{lunch_after_event:b.textContent.replace(/^[A-D]\.\s*/,''),lunch_changed:true,level2_phase:'final-impact',class_state:state,last_impact:change}}))},true)


