if(phase==='standard'){let o=['適合，作為學習表現的獎勵','不太適合，成績和適合坐哪裡沒有直接關係','可以參考，但也應考慮同學相處及上課狀況','不一定，要先知道安排座位想達成什麼目的'];scene('QUESTION 3｜標準適合嗎？','成績適合拿來決定選位順序嗎？','<p>你認為「段考成績」適不適合拿來決定「誰可以優先選座位」？</p>',choose(o));document.querySelectorAll('.l3-choice').forEach(b=>b.onclick=()=>emit({seat_standard_answer:o[+b.dataset.i],level3_phase:'standard-record',last_impact:{}}));return}
