if(phase==='compare'){scene('目的 VS 標準','使用的標準，和目的有關嗎？','<div class="purpose-compare"><section><b>🎯 座位安排可能希望達成：</b><p>良好的學習環境<br>減少彼此干擾<br>兼顧實際需求<br>學生自由與公平機會</p></section><strong>↓　❓　↓</strong><section><b>📊 剛才使用的排序標準：</b><h2>段考成績</h2></section></div><h2>使用的標準，和規則想達成的目的之間，有沒有合理的關係？</h2>',next('boss-intro'));bindNext('boss-intro');return}
if(phase==='boss-intro'){scene('⚠️ WARNING　⚠️ WARNING　⚠️ WARNING','👾 BOSS APPEARS｜多數決巨獸','<p>投票紙與選票飛進教室，組成了一隻巨大的怪獸！</p><div class="boss-hp">BOSS HP <i style="width:100%"></i></div><p>👾「這可是大家投票通過的耶！」<br>👾「而且每個人都按照同一個成績排名！」</p>',next('boss-q','面對巨獸'),true);bindNext('boss-q');return}
if(phase==='boss-q'){let o=['是，只要程序公平、大家適用相同規則就可以','不一定，還要看規則的目的、使用的標準及實際造成的影響'];scene('BOSS QUESTION','多數＋相同標準＝一定合理？','<p>一項規則只要「多數人支持」，而且「每個人都適用相同標準」，就一定公平合理嗎？</p>',choose(o),true);document.querySelectorAll('.l3-choice').forEach(b=>b.onclick=()=>emit({majority_rule_answer:o[+b.dataset.i],level3_phase:'boss-result',boss_first_correct:+b.dataset.i===1,last_impact:{}}));return}
if(phase==='boss-result'){scene('⚔️ BOSS BATTLE','巨獸出現裂縫！',`<div class="boss-hp">BOSS HP <i style="width:${p.boss_first_correct?'55':'76'}%"></i></div><p>${p.boss_first_correct?'⚔️ WEAKNESS！你指出了「目的、標準、影響」都要檢查。':'👾「沒錯！多數萬歲！」<br>⚠️ 但是……真的只需要這樣嗎？'}</p>`,next('final-vote'),true);bindNext('final-vote');return}
