document.addEventListener('click',e=>{let b=e.target.closest&&e.target.closest('#test-back'),heading=document.querySelector('.l2-panel h1')?.textContent;if(!b||heading!=='LEVEL 2 完成')return;e.preventDefault();e.stopImmediatePropagation();let id=JSON.parse(localStorage.getItem('nrc-id')||'null'),db=JSON.parse(localStorage.getItem('no-rule-classroom-demo')||'{}'),key=id&&`${id.class}-${id.seat}`;if(db.students?.[key]){Object.assign(db.students[key],{flow:'level2',level2_phase:'final-impact'});localStorage.setItem('no-rule-classroom-demo',JSON.stringify(db))}location.href='student.html#level2-back'},true)

