 const bindNext=(to,data={})=>document.querySelector('.l3-next').onclick=()=>advance({...data,level3_phase:to,last_impact:{},last_profile_shift:null});
 const options=(items)=>`<div class="options l3-options">${items.map((x,i)=>`<button class="choice l3-choice" data-i="${i}"><b>${'ABCD'[i]}.</b>${x}</button>`).join('')}</div>`;
 const impact=(to,copy)=>{let rows=Object.entries(p.last_impact||{});scene('SYSTEM EFFECT','班級狀態正在改變',`<div class="impact-result l3-impact">${rows.map(([k,v])=>`<span>${names[k]} <strong class="${v>0?'up':'down'}">${v>0?'+':''}${v} ${v>0?'↑':'↓'}</strong></span>`).join('')}</div><p>${copy}</p>`,`<button class="primary" id="l3-impact-next" disabled>繼續看下去</button>`);setTimeout(()=>{let b=document.querySelector('#l3-impact-next');if(b){b.disabled=false;b.onclick=()=>advance({level3_phase:to,last_impact:{},last_profile_shift:null})}},1250);};
 const bubbles=(arr,to,tag='教室裡的聲音',title='每個人都有想坐的位置',end='開始挑戰',prefix='')=>{let i=0;const bind=()=>{document.querySelector('#l3-bubble-next').onclick=()=>{if(i<arr.length-1){i++;draw()}else advance({level3_phase:to,last_impact:{},last_profile_shift:null})}};const draw=()=>{scene(tag,title,`${prefix}<div class="npc-lines storyboard"><p class="speech-bubble">${arr[i]}</p><p class="scene-count">${i+1} / ${arr.length}</p></div>`,i<arr.length-1?`<button class="primary" id="l3-bubble-next">下一句</button>`:`<p class="story-end">每個人都有想坐的位置。<br>但是……誰先選？</p><button class="primary" id="l3-bubble-next">${end}</button>`);bind()};draw()};
 if(phase==='intro')return bubbles(['💬「我要靠窗！」','💬「我想坐後面！」','💬「我不要第一排啦！」','💬「我想跟朋友坐附近。」'],'proposal','🪑 LEVEL 3','黃金座位爭奪戰','開始挑戰');
 if(phase==='proposal')return bubbles(['學生 A：💬「我覺得可以自由選座位啊！」','學生 B：💬「可是大家都想先選，誰先？」','學生 C：💬「不然……按照段考成績？」'],'vote','EVENT 3A｜換座位提案','那……誰先選？','進行表決');
 if(phase==='vote'){scene('🗳️ 班級表決','你支持嗎？','<p>你支持「依段考成績高低決定自由選座位的順序」嗎？</p>',options(['👍 支持','👎 不支持']));document.querySelectorAll('.l3-choice').forEach(b=>b.onclick=()=>{let support=+b.dataset.i===0;advance({seat_vote_real:support?'👍 支持':'👎 不支持',level3_phase:'vote-sent',last_impact:{},last_profile_shift:support?{icon:'🕊️',label:'自由傾向',points:1}:null},{},support?{icon:'🕊️',label:'自由傾向',points:1}:null)});return}
 if(phase==='vote-sent'){scene('📩 表決完成','你的選擇已送出','<p>正在統計表決結果……</p><div class="counting-dots"><i></i><i></i><i></i></div>',next('proposal-passed','查看結果'));bindNext('proposal-passed');return}
 if(phase==='proposal-passed'){scene('🗳️ 表決結果','✨ 提案通過！','<p>📜 本次換座位採用：</p><blockquote>「依段考成績排名，<br>依序自由選位。」</blockquote><p class="note">真正的支持／不支持統計會在老師投影時匿名公布。</p>',next('initial-impact','開始執行'));bindNext('initial-impact');return}
 if(phase==='initial-impact'){advance({level3_phase:'initial-impact-screen'},{freedom:8,empathy:6});return}
 if(phase==='initial-impact-screen')return impact('rank-reveal','大家開始期待自己可以選到喜歡的位置。');
 if(phase==='rank-reveal'){scene('YOUR RESULT','正在讀取你的角色資料……','<div class="rank-count">3　2　1</div><div class="rank-reveal"><i class="avatar-sprite large" style="background-position:${pos}"></i><b>${esc(p.avatar_id)}</b><span>📊 本次選位順位</span><strong>第 ${rank} 名</strong></div><p>前面還有 ${rank-1} 位同學會先選。</p><p class="note">這是角色在遊戲世界中的排名，與你的真實成績無關。</p>',next('seat-preview','看看前面的人怎麼選'));bindNext('seat-preview');return}
 const occupiedCount={2:1,5:3,8:6,11:8,15:10,19:11,24:13,30:14}[rank]||10;
 const blocked=[12,15,13,14,8,11,9,10,4,7,5,6,0,3].slice(0,occupiedCount);
 const seatLabel=i=>{let r=Math.floor(i/4),c=i%4;if(r>=2&&c===0)return ['後排靠窗','back_window'];if(r===0)return ['前排靠近黑板','front'];if(r>=2&&c===1)return ['朋友附近','back_friend'];if(c===0)return ['靠窗','window'];if(c===3)return ['靠走道','aisle'];return ['中間座位','middle']};
 const grid=(selectable=true)=>{let final=selectable==='final';return `<div class="seat-map"><div class="seat-board">⬛ 黑板</div><span class="window-mark">🪟 靠窗</span><div class="seat-grid">${Array.from({length:16},(_,i)=>{let chosen=p.seat_selected_position===i,taken=final?!chosen:blocked.includes(i),friends=final&&[12,13,14].includes(i);return `<button class="seat-cell ${taken?'taken':''} ${chosen?'chosen':''} ${friends?'friends':''}" data-seat="${i}" ${taken||!selectable?'disabled':''}><b>${String(i+1).padStart(2,'0')}</b><small>${chosen?'🧍':friends?'😆😎😂':taken?'👥':'🪑'}</small></button>`}).join('')}</div><span class="aisle-mark">🚪 走道</span></div>`};
 if(phase==='seat-preview'){scene('選位進行中','前面的人先選走熱門座位',`<p>排名越後面，剩下的選擇越少。輪到你時，還有 <b>${16-occupiedCount}</b> 個位置。</p>${grid(false)}`,next('seat-select','輪到我選了'));bindNext('seat-select');return}
 if(phase==='seat-select'){scene('🔔 輪到你了！','剩下的位置中，你想坐哪裡？','<p>可選座位正在發光；灰色位置已被前面的同學選走。</p>'+grid(true));document.querySelectorAll('.seat-cell:not(.taken)').forEach(b=>b.onclick=()=>{let i=+b.dataset.seat,[label,type]=seatLabel(i),few=16-occupiedCount<=3,profile=!few&&(type==='back_window'||type==='window'||type==='aisle'?{icon:'🕊️',label:'自由傾向',points:1}:type==='front'?{icon:'📚',label:'學習傾向',points:1}:type==='back_friend'?{icon:'❤️',label:'同學感受傾向',points:1}:null);advance({seat_selected_position:i,seat_selected_type:type,seat_selected_label:label,seat_selected_limited:few,level3_phase:'seat-confirm',last_impact:{},last_profile_shift:profile},{},profile)});return}
 if(phase==='seat-confirm'){scene('換座位完成','你選擇：'+esc(p.seat_selected_label||'座位'),`<p>${grid(false)}</p><div class="npc-lines storyboard"><p>😆「欸！我們這次坐附近耶！」</p><p>😎「這位置不錯！」</p><p>🙂「終於不用坐第一排了。」</p></div>`,next('final-seating','完成其他同學選位'));bindNext('final-seating');return}
 if(phase==='final-seating'){scene('🪑 FINAL SEATING MAP','換座位完成',`${grid('final')}<div class="seating-results"><p>😆😎😂 幾位熟識同學集中在後排附近。</p><p>💬「其實我想坐前面……輪到我的時候已經沒位置了。」</p><p>💬「我本來想坐後面，結果只剩這裡。」</p><p>第 2 名可選位置很多；第 24 名只剩少數位置。</p></div><p>目前看起來……好像沒什麼問題？</p>`,next('day3','三天後……'));bindNext('day3');return}
 if(phase==='day3')return bubbles(['老師：💬「好，我們看到黑板這裡——」','後排：💬「欸，你昨天那個……」　😂「真的假的啦！」','老師：💬「後面先不要聊天。」','安靜幾秒。','💬「欸欸，你看這個。」　😂「哈哈哈哈！」','老師：💬「後面，真的不要再聊天了。」','旁邊同學：😑「他們真的很吵……」　😵「老師一直停下來，我都不知道上到哪裡了。」'],'late-impact','EVENT 3D｜DAY 1 → DAY 2 → DAY 3','三天後……','查看影響',grid('final'));
 if(phase==='late-impact'){advance({level3_phase:'late-impact-screen'},{learning:-8,order:-10,empathy:-4});return}
 if(phase==='late-impact-screen')return impact('response','朋友聚集後持續聊天；學習效率、班級秩序與同學滿意度都受到影響。');
 if(phase==='response')return bubbles(['NPC 1：💬「可是我們又沒有插隊。」','NPC 2：💬「我們就是照成績排名選的啊。」','NPC 3：💬「而且這個規則不是大家投票通過的嗎？」'],'response-question','EVENT 3E','可是我們有照規則啊！','繼續');
 if(phase==='response-question'){scene('🚨 緊急班級會議','現在怎麼辦？','<p>上課聊天干擾、有人沒有坐到符合需求的位置，排名後面的同學幾乎沒有選擇。</p><h2>你認為現在比較適合怎麼處理？</h2>',options(['維持原座位<br><small>既然大家照規則選好，就先維持。</small>','老師直接調整座位<br><small>把容易互相影響的同學分開。</small>','重新投票<br><small>讓全班重新決定要不要調整。</small>','重新檢討換座位制度<br><small>先重新討論座位安排到底想達成什麼。</small>']));let shifts=[{icon:'⚖️',label:'秩序傾向',points:1},{icon:'📚',label:'學習傾向',points:1},{icon:'🤝',label:'共同責任傾向',points:1},{icon:'🔧',label:'可執行性傾向',points:1}],changes=[{freedom:3,empathy:2,learning:-4,order:-4},{learning:6,order:6,freedom:-5,empathy:-3},{community:3,empathy:2,learning:-2},{community:4,learning:-2}],answers=['維持原座位','老師直接調整座位','重新投票','重新檢討換座位制度'];document.querySelectorAll('.l3-choice').forEach(b=>{let i=+b.dataset.i;b.onclick=()=>advance({seat_response:answers[i],level3_phase:'response-impact',last_profile_shift:shifts[i]},changes[i],shifts[i])});return}
 if(phase==='response-impact')return impact('scanner-intro','這個決定會讓班級朝不同方向改變。');
 if(phase==='scanner-intro'){scene('📜 CURRENT RULE','班級現在決定重新檢查這條規則','<blockquote>「依上次段考總成績排名，從第一名開始依序自由選擇座位。」</blockquote><p>先看看它目前通過了哪些檢查。</p>',next('scanner','啟動 RULE SCANNER'));bindNext('scanner');return}
 if(phase==='scanner'){let scanned=[];scene('🔍 RULE SCANNER','規則掃描器',`<p>逐一掃描這條規則是否通過基本檢查。</p><div class="scanner-options">${['📊 標準清楚嗎？','👥 每個人適用同樣規則嗎？','🗳️ 經過表決嗎？'].map((x,i)=>`<button class="choice scan" data-i="${i}">${x}</button>`).join('')}</div><div id="scan-result"></div><button class="primary" id="scanner-next" disabled>繼續看下去</button>`);document.querySelectorAll('.scan').forEach(b=>b.onclick=()=>{let i=+b.dataset.i;if(scanned.includes(i))return;scanned.push(i);b.classList.add('picked');b.insertAdjacentHTML('beforeend','　✔');document.querySelector('#scan-result').innerHTML=scanned.length===3?'<div class="scanner-error">SYSTEM ERROR<br>⚠️ 全部都通過檢查……為什麼還是出問題？<br>也許……我們檢查錯東西了。</div>':'';if(scanned.length===3)document.querySelector('#scanner-next').disabled=false});document.querySelector('#scanner-next').onclick=()=>advance({level3_phase:'standard',last_impact:{},last_profile_shift:null});return}
 if(phase==='standard'){scene('QUESTION｜標準檢查','📊「段考成績」適合決定誰先選座位嗎？','',options(['適合<br><small>成績好可以得到選位獎勵。</small>','不太適合<br><small>成績和適合坐哪裡沒有直接關係。</small>','可以參考<br><small>但也要考慮實際上課狀況。</small>','等等……<br><small>我們是不是應該先問：「安排座位的目的是什麼？」</small>']));let shifts=[{icon:'📚',label:'學習傾向',points:1},{icon:'⚖️',label:'秩序傾向',points:1},{icon:'🔧',label:'可執行性傾向',points:1},{icon:'🔧',label:'可執行性傾向',points:2}],answers=['適合，作為學習表現的獎勵','不太適合，成績和適合坐哪裡沒有直接關係','可以參考，但也應考慮實際上課狀況','不一定，要先知道安排座位想達成什麼目的'];document.querySelectorAll('.l3-choice').forEach(b=>{let i=+b.dataset.i;b.onclick=()=>advance({seat_standard_answer:answers[i],level3_phase:'standard-record',last_impact:{},last_profile_shift:shifts[i]},{},shifts[i])});return}
 if(phase==='standard-record'){let insight=String(p.seat_standard_answer||'').includes('目的');scene(insight?'✨ INSIGHT!':'判斷已記錄',insight?'你先注意到了「目的」。':'你的判斷已記錄。','<p>一個標準是否合理，要看它和規則想達成的目的有沒有關係。</p>',next('rule-match','進入配對挑戰'));bindNext('rule-match');return}
 if(phase==='rule-match'){let goals=['👓 讓看不清楚黑板的同學能正常上課','🤫 減少容易聊天的同學互相干擾','🎲 讓每個人都有公平選位機會','🏆 獎勵段考表現'],standards=['D. 段考成績','B. 上課互動與干擾狀況','A. 視力／實際座位需求','C. 抽籤／輪流優先'],correct=[2,1,3,0],chosenGoal=null,matches={};scene('🎯 RULE MATCH','規則配對挑戰',`<p>先點一個「目的」，再點最合適的「標準」。</p><div class="rule-match"><section>${goals.map((x,i)=>`<button class="choice goal" data-i="${i}">${i+1}. ${x}</button>`).join('')}</section><section>${standards.map((x,i)=>`<button class="choice standard" data-i="${i}">${x}</button>`).join('')}</section></div><div id="match-status"></div>`);let refresh=()=>{let done=Object.keys(matches).length===4;document.querySelector('#match-status').innerHTML=done?'<div class="match-complete">💥 MATCH COMPLETE<br>🎯 目的　↕　🔗 標準<br>標準本身不一定公平或不公平；重要的是它和目的有沒有合理關係。<br><button class="primary" id="match-next">面對巨獸</button></div>':'<p>已完成：'+Object.keys(matches).length+' / 4</p>';if(done)document.querySelector('#match-next').onclick=()=>advance({seat_rule_match:true,level3_phase:'boss-rule',last_impact:{},last_profile_shift:null})};document.querySelectorAll('.goal').forEach(b=>b.onclick=()=>{chosenGoal=+b.dataset.i;document.querySelectorAll('.goal').forEach(x=>x.classList.toggle('picked',x===b))});document.querySelectorAll('.standard').forEach(b=>b.onclick=()=>{let s=+b.dataset.i;if(chosenGoal===null||matches[chosenGoal]!==undefined)return;if(s!==correct[chosenGoal]){document.querySelector('#match-status').innerHTML='<p class="match-hint">這個標準和目的的關係好像不太直接，再試試看。</p>';return}b.classList.add('matched');matches[chosenGoal]=s;chosenGoal=null;document.querySelectorAll('.goal').forEach(x=>x.classList.remove('picked'));refresh()});refresh();return}
 if(phase==='boss-rule'){scene('📜 BOSS DEFENDS THIS RULE','巨獸正在捍衛哪一條規則？','<blockquote>「依上次段考總成績排名，從第一名開始依序自由選擇座位。」</blockquote>',next('boss-intro','巨獸出現'));bindNext('boss-intro');return}
 if(phase==='boss-intro'){scene('⚠️ WARNING','👾 BOSS APPEARS｜多數決巨獸','<p>投票紙飛入、畫面震動。</p><div class="boss-hp">BOSS HP <i style="width:100%"></i><b>100%</b></div><div class="boss-lines"><p>👾「等一下！」</p><p>👾「這可是大家投票通過的耶！」</p><p>👾「而且每個人都按照同一個標準！」</p></div><div class="boss-equation">🗳️ 多數支持 ＋ 📜 人人適用同一標準 ＝ ❓ 一定合理？</div>',next('boss-q','面對巨獸'),true);bindNext('boss-q');return}
 if(phase==='boss-q'){scene('BOSS QUESTION','多數＋相同標準＝一定合理？','<p>一項規則只要：<br>🗳️ 多數人支持 ＋ 📜 每個人適用相同標準<br>就一定公平合理嗎？</p>',options(['是。<small>程序公平、大家都適用同樣規則就可以。</small>','不一定。<small>還要看目的、標準與實際影響。</small>']),true);document.querySelectorAll('.l3-choice').forEach(b=>{let good=+b.dataset.i===1,shift=good?{icon:'🔧',label:'可執行性傾向',points:1}:null;b.onclick=()=>advance({majority_rule_answer:good?'不一定，還要看目的、標準與實際造成的影響':'是，只要程序公平、大家適用相同規則就可以',boss_first_correct:good,level3_phase:'boss-result',last_impact:{},last_profile_shift:shift},{},shift)});return}
 if(phase==='boss-result'){let good=!!p.boss_first_correct;scene('⚔️ BOSS BATTLE',good?'⚔️ WEAKNESS！':'巨獸仍在咆哮',`<div class="boss-hp"><i style="width:${good?55:76}%"></i><b>${good?55:76}%</b></div><p>${good?'你發現了規則的弱點！<br>🎯 目的　🔗 標準　👥 影響':'👾「沒錯！多數萬歲！」<br>⚠️ 但是……真的只需要這樣嗎？'}</p>`,next('final-vote','繼續戰鬥'),true);bindNext('final-vote');return}
 if(phase==='final-vote'){scene('👾 BOSS HYPOTHESIS','FINAL BOSS ATTACK｜34：1','<div class="vote-box"><strong>24：11　→　28：7　→　32：3</strong><em>34：1</em><span>34 人支持　／　1 人反對</span></div><p>👾「35個人裡有34個人支持！這樣總能證明它是一條好規則了吧？」</p><p class="note">這是 Boss 提出的假設情境，不是本班真實票數。</p>',next('final-q','最後回答'),true);bindNext('final-q');return}
 if(phase==='final-q'){scene('FINAL QUESTION','34：1，就一定合理嗎？','<p>如果35人中有34人支持，只有1人反對，這項規則就一定合理嗎？</p>',options(['一定。<small>多數決的結果就應該接受。</small>','不一定。<small>「有多少人支持」和「規則本身是否合理」是兩個不同問題。</small>']),true);document.querySelectorAll('.l3-choice').forEach(b=>{let good=+b.dataset.i===1,shift=good?{icon:'🔧',label:'可執行性傾向',points:1}:null;b.onclick=()=>advance({seat_final_answer:good?'不一定。多數人支持和規則本身是否合理，是兩個不同的問題':'一定。多數決的結果就應該接受',boss_final_correct:good,level3_phase:good?'defeat':'final-think',last_impact:{},last_profile_shift:shift},{},shift)});return}
 if(phase==='final-think'){scene('⚠️ FINAL CHECK','再想一想','<p>👾「看吧！34個人耶！」</p><p>如果 34 個人決定：最後 1 個人每天替全班打掃，只因為 34 個人支持，這項規則就合理嗎？</p>',next('final-q','重新思考'),true);bindNext('final-q');return}
 if(phase==='defeat'){scene('💥 BOSS DEFEATED','多數決巨獸消散了','<div class="boss-hp"><i style="width:0%"></i><b>0%</b></div><div class="boss-lines"><p>👾「怎麼可能……」</p><p>👾「明明這麼多人支持……」</p></div><p>多數決沒有失效。它仍然可以幫助群體在不同意見中形成共同決定。</p><h2>但是——</h2><h1>「多數決可以決定結果，卻不能自動證明結果合理。」</h1>',next('skill','解鎖技能'),true);bindNext('skill');return}
 if(phase==='skill'){let unlocked=Array.from(new Set([...(p.unlocked||[]),'⚖️ 規範合理性']));scene('🔓 SKILL UNLOCKED','⚖️ 規範合理性','<div class="skill-card"><b>判斷規範時，可以問：</b><p>🎯 PURPOSE｜這項規範想達成什麼？</p><p>🔗 CONNECTION｜使用的標準和目的有合理關係嗎？</p><p>👥 IMPACT｜實際執行會造成什麼影響？</p><hr><p>「大家都一樣」不一定等於公平。<br>「大多數人支持」也不一定等於合理。</p></div>',next('clear','查看通關結果',{unlocked}));bindNext('clear',{unlocked});return}
