window.NRC_COMPLETE_LEVEL=window.NRC_SHARED_COMPLETE_LEVEL;
window.NRC_SHOW_L3_REPLAY=()=>{document.querySelector('#stage-label').textContent='LEVEL 3｜黃金座位爭奪戰';document.querySelector('#app').innerHTML=`<section class="paper l3-replay"><p class="eyebrow">🪑 LEVEL 3</p><h1>✅ 已完成</h1><p>你已完成「黃金座位爭奪戰」。</p><button class="primary" id="l3-retry">再次挑戰</button><button class="secondary" id="l3-stay-hub">返回教室</button></section>`;document.querySelector('#l3-retry').onclick=()=>document.dispatchEvent(new CustomEvent('level2-action',{detail:{flow:'level3',level3_phase:'intro',last_impact:{},last_profile_shift:null}}));document.querySelector('#l3-stay-hub').onclick=()=>window.NRC_RETURN_TO_HUB({flow:'hub',last_impact:{}})};
window.NRC_SYNC_HUB=async()=>{let id=JSON.parse(localStorage.getItem('nrc-id')||'null'),p=id&&await GameAPI.call('getStudent',id);if(!p||p.flow!=='hub')return;let side=document.querySelector('.hotspot.side');if(side&&p.level4_cleared){side.classList.remove('locked');side.classList.add('new');side.innerHTML='<b>👾 規則漏洞大決戰</b><span>FINAL BOSS</span>'}console.debug('[Hub] level2 status =',p.level2_cleared?'CLEARED':p.level1_cleared?'NEW':'LOCKED');console.debug('[Hub] level3 status =',p.level3_cleared?'CLEARED':p.level2_cleared?'NEW':'LOCKED');console.debug('[Hub] level4 status =',p.level4_cleared?'CLEARED':p.level3_cleared?'NEW':'LOCKED');return p};
setTimeout(()=>window.NRC_SYNC_HUB(),0);
